namespace qqworld_collector\module\collect_filter; class convert_files extends filter { var $mime_types; public function create_new_attachment($attachment_id, $format, $return = 'ID', $size = 'full') { if (wp_attachment_is_image($attachment_id)) { $new_attachment_id = $GLOBALS['QC']->auto_save_attachment->save_attachment->convert_file_format->convert_to($attachment_id, $format, 'new'); if ($new_attachment_id != $attachment_id) { if ($this->options->cloud_storage_enabled) do_action( 'qqworld-collector-cloud-storage-sync-single-attachment', $new_attachment_id ); switch ($return) { case 'url': $attachment_id = wp_get_attachment_url($new_attachment_id, $size); break; case 'ID': default: $attachment_id = $new_attachment_id; break; } } } return $attachment_id; } public function create_new_file($url, $format) { $parser = parse_url($url); $filepath = ABSPATH . preg_replace('/^\//', '', $parser['path']); $source_type = mime_content_type($filepath); $source_type = preg_replace('/^[^\/]*\//i', '', $source_type); $ext = $source_type == 'jpeg' ? 'jpg' : $source_type; $file = apply_filters( 'qqworld-collector-convert-file-format', file_get_contents($filepath), $source_type, $format ); if ( apply_filters( 'qqworld-collector-convert-file-format-successed', false ) ) { $filepath = preg_replace('/\.'.$ext.'$/i', '.'.$format, $filepath); file_put_contents($filepath, $file); $url = preg_replace('/\.'.$ext.'$/', '.'.$format, $url); } return $url; } public function filter($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode) { if ($mode != 'test') { $convert = isset($args['convert']) ? $args['convert'] : ''; if (!$convert) return $item; if ( is_numeric($item)) { $attachment_id = intval($item); $item = $this->create_new_attachment($attachment_id, $convert); } else { $url = apply_filters( 'qqworld-collector-convert-relative-url-to-absolute-url', $item, $source_link); $parser = parse_url(home_url()); $host = preg_replace('/^www\./i', '', $parser['host']); if (strstr($url, $host) !== false) { if ( preg_match('/wp\-json\/cs\/v1\/(\d*)/i', $url, $match) ) { $attachment_id = intval($match[1]); $item = $this->create_new_attachment($attachment_id, $convert, 'url'); } else { $item = $this->create_new_file($url, $convert); } } else { if ( !$GLOBALS['QC']->auto_save_attachment->save_attachment->is_remote_attachment($url) ) { if ( preg_match('/\/\d{4}\/\d{2}\/[^\?]*/i', $url, $match) ) { $filepath = WP_CONTENT_DIR . DIRECTORY_SEPARATOR . 'uploads' . $match[0]; if (file_exists($filepath)) { $url = WP_CONTENT_URL . '/uploads' . $match[0]; $item = $this->create_new_file($url, $convert); return $item; } } } else { $headers = apply_filters( 'qqworld-collector-get-headers-from-url', $url, $download_args); if ($headers) { add_filter( 'qqworld-collector-after-download-attachment-from-url', array($this, 'after_download_attachment'), 10, 2 ); $this->targat_type = $convert; $GLOBALS['QC']->auto_save_attachment->save_attachment->download_args = $download_args; $attachment = $GLOBALS['QC']->auto_save_attachment->save_attachment->grab_attachment_url($url, null, 'local'); remove_filter( 'qqworld-collector-after-download-attachment-from-url', array($this, 'after_download_attachment') ); if ( strstr($attachment['type'], 'image') !== false ) { if ( isset($attachment['sizes']) && isset($attachment['sizes']['full']) ) { $item = $attachment['sizes']['full']['url']; } } else { if ( isset($attachment['file_src']) ) { $item = $attachment['file_src']; } } } } } } } return $item; } public function after_download_attachment($remote_attachment, $download_args) { $preg = preg_match( '/[^\/]*$/i', $remote_attachment['type'], $match); if ($preg) { $source_type = $match[0]; if ($source_type != $this->targat_type) { $file = apply_filters( 'qqworld-collector-convert-file-format', $remote_attachment['file'], $source_type, $this->targat_type ); if ( apply_filters( 'qqworld-collector-convert-file-format-successed', false ) ) { $remote_attachment['file'] = $file; $remote_attachment['type'] = 'image/'.$this->targat_type; } } } return $remote_attachment; } } ?>